mapper.update:
	UPDATE  /* SQL-ID : isry.couns.constt.medscsnntabrd.mapper.BbssoldListMapper.updateReply : 게시글수정 */
            AYE110  
	SET
            CMNT_CN                 =       #{CMNT_CN}
        ,   CNTN_IP_ADDR            =       #{CNTN_IP_ADDR}
        ,   LAST_MDFCN_DT           =       SYSDATE      
        ,   LAST_MDFR_ID            =       #{LAST_MDFR_ID}
    WHERE   1=1
        AND BBSCTT_ESNTAL_NO        =       #{BBSCTT_ESNTAL_NO}
        AND BBSCTT_TYPE_SE_CD       =       '02'                   /*  게시판유형구분코드  */
        AND CMNT_ESNTAL_NO          =       #{CMNT_ESNTAL_NO}

	UPDATE  /* SQL-ID : isry.couns.constt.medscsnntabrd.mapper.BbssoldListMapper.deleteReply : 댓글삭제 */
	        AYE110 
	SET
            DEL_YN                 =       'Y'
        ,   LAST_MDFCN_DT          =       SYSDATE      
        ,   LAST_MDFR_ID           =       #{LAST_MDFR_ID}    
    WHERE   1=1
        AND BBSCTT_ESNTAL_NO       =       #{BBSCTT_ESNTAL_NO}
        AND BBSCTT_TYPE_SE_CD      =       '02'                   /*  게시판유형구분코드  */
        AND CMNT_ESNTAL_NO         =       #{CMNT_ESNTAL_NO}

UPDATE  /* isry.couns.constt.medscsnntabrd.mapper.BbssoldListMapper.updateCrisisBoard : 솔로봇채팅 위기유형등록 */
        AYA110  
SET
        CRISIS_TYPE_SE_CD       =       #{CRISIS_TYPE_SE_CD} 
    ,   LAST_MDFR_ID            =       #{LAST_MDFR_ID}
    ,   LAST_MDFCN_DT           =       SYSDATE
WHERE   1=1
    AND BBSCTT_ESNTAL_NO       =       #{BBSCTT_ESNTAL_NO}
    AND BBSCTT_TYPE_SE_CD      =       '02'                   /*  게시판유형구분코드  */

UPDATE  /* isry.couns.constt.medscsnntabrd.mapper.BbssoldListMapper.updateCrisisPerson : 솔로봇채팅 위기유형등록 */
        AYA120  
SET
        CRISIS_TYPE_SE_CD       =       #{CRISIS_TYPE_SE_CD} 
    ,   CLIENA_ID               =       #{CLIENA_ID}
    ,   LAST_MDFR_ID            =       #{LAST_MDFR_ID}
    ,   LAST_MDFCN_DT           =       SYSDATE
WHERE   1=1
    AND BBSCTT_ESNTAL_NO       =       #{BBSCTT_ESNTAL_NO}
    AND BBSCTT_TYPE_SE_CD      =       '02'                   /*  게시판유형구분코드  */

UPDATE  /* isry.couns.constt.medscsnntabrd.mapper.BbscttListMapper.updateMemo : 비밀게시판 메모수정 */
        AYA160
SET
        MEMO_NM                 =       #{MEMO_NM}
    ,   LAST_MDFR_ID            =       #{LAST_MDFR_ID}
    ,   LAST_MDFCN_DT           =       SYSDATE
WHERE   1=1
    AND BBSCTT_ESNTAL_NO        =       #{BBSCTT_ESNTAL_NO}
    AND BBSCTT_TYPE_SE_CD       =       '02'

UPDATE  /* isry.couns.constt.medscsnntabrd.mapper.BbscttListMapper.updateProbmStts : 문제상태수정 */
        AYE100
SET
        PROBM_STTS_LCLAS_SE_CD          =       #{PROBM_STTS_LCLAS_SE_CD}
    ,   PROBM_STTS_MLSFC_SE_CD          =       #{PROBM_STTS_MLSFC_SE_CD}
    ,   PROBM_STTS_SCLAS_SE_CD          =       #{PROBM_STTS_SCLAS_SE_CD}
    ,   PROBM_CAS_LCLAS_SE_CD           =       #{PROBM_CAS_LCLAS_SE_CD}
    ,   PROBM_CAS_SCLAS_SE_CD           =       #{PROBM_CAS_SCLAS_SE_CD}
    ,   ETC_CN                          =       #{ETC_CN}
    ,   LAST_MDFR_ID                    =       #{LAST_MDFR_ID}
    ,   LAST_MDFCN_DT                   =       SYSDATE
WHERE   1=1
    AND BBSCTT_ESNTAL_NO                =       #{BBSCTT_ESNTAL_NO}
    AND BBSCTT_TYPE_SE_CD               =       '02'
